"use client";

import { type KeyboardEvent, type PointerEvent, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { RefreshIcon } from "../parts/icons";
import { RollingText } from "../parts/rolling-text";
import { ChartHeader } from "./gantt-timeline/chart-header";
import { CHART_DAYS, CHART_TODAY, chartLabel, GANTT_GROUPS, type GanttGroup, type GanttTask } from "./gantt-timeline/data";
import { DependencyLines } from "./gantt-timeline/dependency-lines";
import { buildRows, DAY_REM, type GanttDrag, preview, type Zoom } from "./gantt-timeline/rows";
import { TaskBar } from "./gantt-timeline/task-bar";
import { TaskList } from "./gantt-timeline/task-list";
import { UndoIcon } from "./shared/icons";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

const ZOOMS: { value: Zoom; label: string }[] = [
  { value: "day", label: "Day" },
  { value: "week", label: "Week" },
  { value: "month", label: "Month" },
];

const mapTasks = (groups: GanttGroup[], change: (task: GanttTask) => GanttTask) =>
  groups.map((group) => ({ ...group, tasks: group.tasks.map(change) }));

/**
 * A project timeline. Drag a bar to move it, or pull an edge to change its
 * dates; it snaps to whole days when let go. Arrows, group summaries and the
 * task list read the same values, so they move together. From the keyboard,
 * up and down walk the bars, Alt with left or right moves one a day, and
 * Shift with Alt changes its length.
 */
export function GanttTimeline({ className }: { className?: string }) {
  const [groups, setGroups] = useState(GANTT_GROUPS);
  const [history, setHistory] = useState<GanttGroup[][]>([]);
  const [zoom, setZoom] = useState<Zoom>("week");
  const [closed, setClosed] = useState<Set<string>>(() => new Set());
  const [drag, setDrag] = useState<GanttDrag | null>(null);
  const [focusId, setFocusId] = useState("survey");
  const [announce, setAnnounce] = useState("");
  const origin = useRef({ x: 0 });
  const canvasRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const titleId = useId();
  const helpId = useId();

  const dayRem = DAY_REM[zoom];
  const widthRem = CHART_DAYS * dayRem;
  const rows = buildRows(groups, closed, drag);
  const all = groups.flatMap((group) => group.tasks);
  const totalDays = all.reduce((sum, task) => sum + (task.end - task.start), 0);
  const percent = Math.round(all.reduce((sum, task) => sum + (task.end - task.start) * task.done, 0) / totalDays);
  const taskIds = rows.flatMap((row) => (row.kind === "task" ? [row.task.id] : []));
  const tabStop = taskIds.includes(focusId) ? focusId : taskIds[0];

  const commit = (next: GanttGroup[], message: string) => {
    setHistory((current) => [...current.slice(-19), groups]);
    setGroups(next);
    setAnnounce(message);
  };

  const describe = (task: GanttTask) => `${task.name} now runs ${chartLabel(task.start)} to ${chartLabel(task.end - 1)}.`;

  const startDrag = (event: PointerEvent<HTMLElement>, id: string, mode: GanttDrag["mode"]) => {
    if (event.button !== 0) return;
    event.preventDefault();
    canvasRef.current?.setPointerCapture(event.pointerId);
    origin.current = { x: event.clientX };
    setFocusId(id);
    setDrag({ id, mode, delta: 0 });
  };

  const onPointerMove = (event: PointerEvent) => {
    if (!drag) return;
    const width = canvasRef.current?.getBoundingClientRect().width ?? 1;
    setDrag({ ...drag, delta: (event.clientX - origin.current.x) / (width / CHART_DAYS) });
  };

  const endDrag = () => {
    if (!drag) return;
    const moved = Math.round(drag.delta) !== 0;
    const task = all.find((item) => item.id === drag.id);
    if (moved && task) {
      const changed = preview(task, drag, true);
      commit(
        mapTasks(groups, (item) => (item.id === task.id ? changed : item)),
        describe(changed),
      );
    }
    setDrag(null);
  };

  const onBarKey = (event: KeyboardEvent<HTMLElement>, task: GanttTask) => {
    if (event.key === "ArrowUp" || event.key === "ArrowDown") {
      event.preventDefault();
      const index = taskIds.indexOf(task.id) + (event.key === "ArrowDown" ? 1 : -1);
      const nextId = taskIds[Math.max(0, Math.min(taskIds.length - 1, index))];
      if (!nextId) return;
      setFocusId(nextId);
      const bar = canvasRef.current?.querySelector<HTMLElement>(`[data-bar="${nextId}"]`);
      bar?.focus({ preventScroll: true });
      bar?.scrollIntoView({ block: "nearest", inline: "nearest" });
      return;
    }
    if (!event.altKey || (event.key !== "ArrowLeft" && event.key !== "ArrowRight")) return;
    event.preventDefault();
    const step = event.key === "ArrowRight" ? 1 : -1;
    const moved = preview(task, { id: task.id, mode: event.shiftKey ? "end" : "move", delta: step }, true);
    if (moved.start === task.start && moved.end === task.end) return;
    commit(
      mapTasks(groups, (item) => (item.id === task.id ? moved : item)),
      describe(moved),
    );
  };

  const toToday = () => {
    const box = scrollRef.current;
    if (!box) return;
    const remPx = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
    box.scrollTo({ left: CHART_TODAY * dayRem * remPx - box.clientWidth / 3, behavior: "smooth" });
  };

  const undo = () => {
    const last = history[history.length - 1];
    if (!last) return;
    setGroups(last);
    setHistory(history.slice(0, -1));
    setAnnounce("Undid the last change.");
  };

  const snapped = drag ? all.find((task) => task.id === drag.id) : undefined;
  const target = snapped && drag ? preview(snapped, drag, true) : null;
  const targetRow = target ? rows.findIndex((row) => row.kind === "task" && row.task.id === target.id) : -1;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <h2 id={titleId} className="flex items-baseline gap-2 text-base font-semibold">
          Evening hours launch
          <span className="flex items-baseline text-sm font-normal text-muted-foreground">
            <RollingText text={`${percent}%`} />
            &nbsp;done
          </span>
        </h2>
        <div className="flex flex-wrap items-center gap-2">
          <SegmentedControl aria-label="Zoom" options={ZOOMS} value={zoom} onValueChange={setZoom} />
          <Button variant="outline" size="sm" onClick={toToday}>
            Today
          </Button>
        </div>
      </header>

      <p id={helpId} className="sr-only">
        Up and down move between bars. Alt with left or right moves the task a day. Shift and Alt with left or right changes its length.
      </p>
      <p className="sr-only" aria-live="polite">
        {announce}
      </p>

      <div className="grid grid-cols-[9.5rem_1fr] @xl:grid-cols-[14rem_1fr]">
        <TaskList
          rows={rows}
          onToggle={(id) =>
            setClosed((current) => {
              const next = new Set(current);
              if (next.has(id)) next.delete(id);
              else next.add(id);
              return next;
            })
          }
        />
        <div ref={scrollRef} className="scroll-fade-effect-x scrollbar-none min-w-0 overflow-x-auto">
          <div style={
            // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
            { "--width": `${widthRem}rem` } as VarStyle
          } className="w-(--width) motion-safe:transition-all motion-safe:duration-300">
            <ChartHeader zoom={zoom} />
            <div
              ref={canvasRef}
              onPointerMove={onPointerMove}
              onPointerUp={endDrag}
              onPointerCancel={() => setDrag(null)}
              className="relative"
            >
              {zoom !== "month"
                ? Array.from({ length: Math.ceil(CHART_DAYS / 7) }, (_, week) => (
                    <span
                      key={week}
                      aria-hidden="true"
                      className="left-(--left) absolute inset-y-0 border-l border-border"
                      style={
                        // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                        { "--left": `${week * 7 * dayRem}rem` } as VarStyle
                      }
                    />
                  ))
                : null}
              <span
                aria-hidden="true"
                className="left-(--left) absolute inset-y-0 z-10 border-l-2 border-chart-5"
                style={
                  // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                  { "--left": `${(CHART_TODAY + 0.5) * dayRem}rem` } as VarStyle
                }
              />
              {target && targetRow >= 0 ? (
                <span
                  aria-hidden="true"
                  className="top-(--top) left-(--left) w-(--width) absolute z-0 h-6 rounded-md border-2 border-dashed border-foreground/50"
                  style={
                    // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                    { "--top": `${targetRow * 2.25 + 0.375}rem`, "--left": `${target.start * dayRem}rem`, "--width": `${(target.end - target.start) * dayRem}rem` } as VarStyle
                  }
                >
                  <span className="absolute -top-5 left-0 rounded bg-popover px-1 text-xs whitespace-nowrap text-popover-foreground shadow">
                    {chartLabel(target.start)} to {chartLabel(target.end - 1)}
                  </span>
                </span>
              ) : null}
              <DependencyLines rows={rows} dayRem={dayRem} widthRem={widthRem} />
              <ul aria-label="Timeline">
                {rows.map((row) =>
                  row.kind === "group" ? (
                    <li key={row.group.id} className="relative h-9" aria-label={`${row.group.name}, ${Math.round(row.done)}% done`}>
                      <span
                        aria-hidden="true"
                        className={cn(
                          "left-(--left) w-(--width) absolute top-3.5 h-2 overflow-hidden rounded-full bg-muted-foreground/30",
                          !drag && "motion-safe:transition-all motion-safe:duration-300",
                        )}
                        style={
                          // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                          { "--left": `${row.start * dayRem}rem`, "--width": `${(row.end - row.start) * dayRem}rem` } as VarStyle
                        }
                      >
                        <span className="w-(--width) absolute inset-y-0 left-0 rounded-full bg-foreground/70" style={
                          // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
                          { "--width": `${row.done}%` } as VarStyle
                        } />
                      </span>
                    </li>
                  ) : (
                    <li key={row.task.id} className="relative h-9">
                      <TaskBar
                        task={row.task}
                        dayRem={dayRem}
                        dragging={drag?.id === row.task.id}
                        focusable={tabStop === row.task.id}
                        helpId={helpId}
                        onPointerDown={(event, mode) => startDrag(event, row.task.id, mode)}
                        onKeyDown={(event) => onBarKey(event, row.task)}
                        onFocus={() => setFocusId(row.task.id)}
                      />
                    </li>
                  ),
                )}
              </ul>
            </div>
          </div>
        </div>
      </div>

      <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-5 py-3">
        <p className="text-xs text-muted-foreground">Drag a bar to move it, or pull an edge to change its dates.</p>
        <div className="flex gap-1">
          <Button variant="ghost" size="sm" onClick={undo} disabled={history.length === 0}>
            <UndoIcon />
            Undo
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => commit(GANTT_GROUPS, "Timeline reset.")}
            disabled={history.length === 0}
          >
            <RefreshIcon />
            Reset
          </Button>
        </div>
      </footer>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
