import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import { cn } from "@/lib/utils";

import { CHART_DAYS, CHART_TODAY, chartDate, chartLabel, chartMonth } from "./data";
import { DAY_REM, type Zoom } from "./rows";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/**
 * The date ruler over the chart. Day zoom marks every day, week zoom marks
 * each Monday, month zoom marks each first of the month. Today wears a pill.
 */
export function ChartHeader({ zoom }: { zoom: Zoom }) {
  const width = DAY_REM[zoom];
  const ticks = Array.from({ length: CHART_DAYS }, (_, day) => day).filter((day) => {
    if (zoom === "day") return true;
    if (zoom === "week") return day % 7 === 0;
    return day === 0 || chartDate(day).getUTCDate() === 1;
  });

  return (
    <div aria-hidden="true" className="relative h-11 border-b border-border">
      {ticks.map((day) => (
        <span
          key={day}
          className={cn(
            "left-(--left) absolute bottom-1.5 text-xs whitespace-nowrap tabular-nums text-muted-foreground motion-safe:transition-all motion-safe:duration-300",
            zoom === "day" && "w-9 text-center",
          )}
          style={
            // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
            { "--left": `${day * width}rem` } as VarStyle
          }
        >
          {zoom === "day" ? chartDate(day).getUTCDate() : zoom === "week" ? chartLabel(day) : chartMonth(day)}
        </span>
      ))}
      {zoom !== "month" ? (
        <span className="absolute top-1.5 left-1 text-xs font-medium">{chartMonth(0)} to December</span>
      ) : null}
      <span
        className="left-(--left) absolute top-1 -translate-x-1/2 rounded-full bg-primary px-1.5 text-xs font-semibold text-primary-foreground motion-safe:transition-all motion-safe:duration-300"
        style={
          // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
          { "--left": `${(CHART_TODAY + 0.5) * width}rem` } as VarStyle
        }
      >
        Today
      </span>
    </div>
  );
}

/** One task on the timeline. Days count from Monday, Oct 19, 2026; `end` is the day after the last day. */
export interface GanttTask {
  id: string;
  name: string;
  owner: string;
  start: number;
  end: number;
  /** How much is done, from 0 to 100. */
  done: number;
  /** The task that must finish first, if any. */
  after?: string;
}

/** A named group of tasks. */
export interface GanttGroup {
  id: string;
  name: string;
  tasks: GanttTask[];
}

/** The number of days the chart covers: Oct 19 to Dec 31, 2026. */
export const CHART_DAYS = 74;

/** Today, as a chart day: Wednesday, Nov 11. */
export const CHART_TODAY = 23;

/** The sample project: opening evening hours at ten clinics. */
export const GANTT_GROUPS: GanttGroup[] = [
  {
    id: "research",
    name: "Research",
    tasks: [
      { id: "survey", name: "Patient demand survey", owner: "noor", start: 0, end: 9, done: 100 },
      { id: "staffing", name: "Staffing model", owner: "tomas", start: 7, end: 18, done: 80, after: "survey" },
    ],
  },
  {
    id: "build",
    name: "Build",
    tasks: [
      { id: "rota", name: "Evening rota in the app", owner: "ines", start: 18, end: 32, done: 45, after: "staffing" },
      { id: "booking", name: "Late slots on booking page", owner: "kofi", start: 21, end: 35, done: 30 },
      { id: "reminders", name: "Evening reminder texts", owner: "lena", start: 32, end: 40, done: 0, after: "rota" },
    ],
  },
  {
    id: "rollout",
    name: "Rollout",
    tasks: [
      { id: "pilot", name: "Pilot at Harbour Street", owner: "arjun", start: 40, end: 50, done: 0, after: "reminders" },
      { id: "train", name: "Train front desks", owner: "noor", start: 44, end: 54, done: 0, after: "booking" },
      { id: "launch", name: "Open in ten clinics", owner: "ines", start: 54, end: 66, done: 0, after: "pilot" },
    ],
  },
];

const BASE = Date.UTC(2026, 9, 19);
const SHORT = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const MONTH = new Intl.DateTimeFormat("en-US", { month: "long", timeZone: "UTC" });

/** The date of a chart day. */
export const chartDate = (day: number) => new Date(BASE + day * 86_400_000);

/** A short date for a chart day, such as Nov 11. */
export const chartLabel = (day: number) => SHORT.format(chartDate(day));

/** The month name of a chart day. */
export const chartMonth = (day: number) => MONTH.format(chartDate(day));

import { CHART_DAYS, type GanttGroup, type GanttTask } from "./data";

/** How wide one day is at each zoom, in rem. */
export const DAY_REM = { day: 2.25, week: 0.9, month: 0.4 } as const;

/** One zoom level. */
export type Zoom = keyof typeof DAY_REM;

/** The height of one row, in rem. It matches `h-9`. */
export const ROW_REM = 2.25;

/** One visible row: a group with its summary span, or a task. */
export type GanttRow =
  | { kind: "group"; group: GanttGroup; start: number; end: number; done: number; open: boolean }
  | { kind: "task"; task: GanttTask };

/** A bar being dragged: which task, which part, and how many days it has moved so far, unsnapped. */
export interface GanttDrag {
  id: string;
  mode: "move" | "start" | "end";
  delta: number;
}

/** A task as the drag shows it right now, so the bar, its arrows and its group summary read one value. */
export function preview(task: GanttTask, drag: GanttDrag | null, snap = false): GanttTask {
  if (!drag || drag.id !== task.id) return task;
  const delta = snap ? Math.round(drag.delta) : drag.delta;
  if (drag.mode === "move") {
    const shift = Math.max(-task.start, Math.min(CHART_DAYS - task.end, delta));
    return { ...task, start: task.start + shift, end: task.end + shift };
  }
  if (drag.mode === "start") return { ...task, start: Math.max(0, Math.min(task.end - 1, task.start + delta)) };
  return { ...task, end: Math.min(CHART_DAYS, Math.max(task.start + 1, task.end + delta)) };
}

/** The rows on screen: each group, then its tasks when the group is open. A group's span and progress follow its tasks. */
export function buildRows(groups: GanttGroup[], closed: Set<string>, drag: GanttDrag | null): GanttRow[] {
  return groups.flatMap((group) => {
    const tasks = group.tasks.map((task) => preview(task, drag));
    const length = tasks.reduce((sum, task) => sum + (task.end - task.start), 0);
    const doneDays = tasks.reduce((sum, task) => sum + ((task.end - task.start) * task.done) / 100, 0);
    const open = !closed.has(group.id);
    const head: GanttRow = {
      kind: "group",
      group,
      start: Math.min(...tasks.map((task) => task.start)),
      end: Math.max(...tasks.map((task) => task.end)),
      done: length === 0 ? 0 : (doneDays / length) * 100,
      open,
    };
    return open ? [head, ...tasks.map((task): GanttRow => ({ kind: "task", task }))] : [head];
  });
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

import type { GanttRow } from "./rows";
import { ROW_REM } from "./rows";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/**
 * The "after" arrows between bars, drawn in rem so they share the bars'
 * numbers: each one leaves the end of the first task and enters the start of
 * the one that waits for it. Arrows to a task in a closed group are left out.
 */
export function DependencyLines({ rows, dayRem, widthRem }: { rows: GanttRow[]; dayRem: number; widthRem: number }) {
  const heightRem = rows.length * ROW_REM;
  const place = new Map(
    rows.flatMap((row, index) => (row.kind === "task" ? [[row.task.id, { task: row.task, y: (index + 0.5) * ROW_REM }] as const] : [])),
  );
  const paths = [...place.values()].flatMap(({ task, y }) => {
    const from = task.after ? place.get(task.after) : undefined;
    if (!from) return [];
    const x1 = from.task.end * dayRem;
    const x2 = task.start * dayRem;
    const bend = x1 + 0.5;
    const line = x2 - 0.6 > x1 ? `M${x1} ${from.y}H${bend}V${y}H${x2}` : `M${x1} ${from.y}h0.5V${y - ROW_REM / 2}H${x2 - 0.6}V${y}H${x2}`;
    const head = `M${x2 - 0.35} ${y - 0.22}L${x2} ${y}L${x2 - 0.35} ${y + 0.22}`;
    return [{ id: task.id, line, head }];
  });

  return (
    <svg
      aria-hidden="true"
      className="w-(--width) h-(--height) pointer-events-none absolute top-0 left-0 text-muted-foreground"
      style={
        // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
        { "--width": `${widthRem}rem`, "--height": `${heightRem}rem` } as VarStyle
      }
      viewBox={`0 0 ${widthRem} ${heightRem}`}
      preserveAspectRatio="none"
      fill="none"
    >
      {paths.map((path) => (
        <g key={path.id} stroke="currentColor" strokeWidth="1.25" vectorEffect="non-scaling-stroke" strokeLinejoin="round">
          <path d={path.line} vectorEffect="non-scaling-stroke" />
          <path d={path.head} vectorEffect="non-scaling-stroke" />
        </g>
      ))}
    </svg>
  );
}

