/** Props for one draggable task bar. */
export interface TaskBarProps {
  task: GanttTask;
  dayRem: number;
  /** True while dragged: the bar follows the pointer with no easing. */
  dragging: boolean;
  focusable: boolean;
  helpId: string;
  onPointerDown: (event: PointerEvent<HTMLElement>, mode: "move" | "start" | "end") => void;
  onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
  onFocus: () => void;
}

/**
 * One task as a bar: tinted in its owner's hue, filled to its percent done,
 * with its name inside. Drag the body to move it, or either edge to change its
 * dates. It glides to a new place when released or zoomed.
 */
export function TaskBar({ task, dayRem, dragging, focusable, helpId, onPointerDown, onKeyDown, onFocus }: TaskBarProps) {
  const hue = person(task.owner).hue;
  const lastDay = Math.round(task.end) - 1;
  return (
    <div
      role="button"
      data-bar={task.id}
      tabIndex={focusable ? 0 : -1}
      aria-label={`${task.name}, ${chartLabel(Math.round(task.start))} to ${chartLabel(lastDay)}, ${task.done}% done`}
      aria-describedby={helpId}
      onPointerDown={(event) => onPointerDown(event, "move")}
      onKeyDown={onKeyDown}
      onFocus={onFocus}
      className={cn(
        "left-(--left) w-(--width) group absolute top-1.5 isolate flex h-6 cursor-grab touch-none items-center overflow-hidden rounded-md border text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring",
        HUE_BORDER[hue],
        dragging ? "z-10 cursor-grabbing shadow-lg" : "motion-safe:transition-all motion-safe:duration-300 motion-safe:ease-out",
      )}
      style={
        // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
        { "--left": `${task.start * dayRem}rem`, "--width": `${(task.end - task.start) * dayRem}rem` } as VarStyle
      }
    >
      <span aria-hidden="true" className={cn("left-(--left) w-(--width) absolute inset-0 -z-10 opacity-20", HUE_FILL[hue])} />
      <span aria-hidden="true" className={cn("w-(--width) absolute inset-y-0 left-0 -z-10 opacity-50", HUE_FILL[hue])} style={
        // SAFETY: the keys are CSS custom properties, which CSSProperties does not list.
        { "--width": `${task.done}%` } as VarStyle
      } />
      <span className="truncate px-2 font-medium">{task.name}</span>
      <span className="ml-auto pr-2 tabular-nums text-muted-foreground">{task.done}%</span>
      <span
        aria-hidden="true"
        onPointerDown={(event) => {
          event.stopPropagation();
          onPointerDown(event, "start");
        }}
        className="absolute inset-y-0 left-0 w-2 cursor-ew-resize"
      />
      <span
        aria-hidden="true"
        onPointerDown={(event) => {
          event.stopPropagation();
          onPointerDown(event, "end");
        }}
        className="absolute inset-y-0 right-0 w-2 cursor-ew-resize"
      />
    </div>
  );
}

/** The five chart hues, in order. A person or a calendar takes one by index. */
export type Hue = 1 | 2 | 3 | 4 | 5;

/** One member of the Fernhill team, used across the project blocks. */
export interface Person {
  id: string;
  name: string;
  initials: string;
  hue: Hue;
}

/** The Fernhill team. Every block draws its owners, attendees and authors from this list. */
export const TEAM: Person[] = [
  { id: "ines", name: "Ines Varga", initials: "IV", hue: 1 },
  { id: "tomas", name: "Tomas Reyes", initials: "TR", hue: 2 },
  { id: "noor", name: "Noor Haddad", initials: "NH", hue: 3 },
  { id: "kofi", name: "Kofi Mensah", initials: "KM", hue: 4 },
  { id: "lena", name: "Lena Brandt", initials: "LB", hue: 5 },
  { id: "arjun", name: "Arjun Patel", initials: "AP", hue: 2 },
];

/** The person with this id. Unknown ids fall back to the first person, so sample data never renders blank. */
export function person(id: string): Person {
  return TEAM.find((member) => member.id === id) ?? TEAM[0]!;
}

/** A solid fill in each hue, for a bar, a dot or a marker. Written out so the class lint can read every name. */
export const HUE_FILL = {
  1: "bg-chart-1",
  2: "bg-chart-2",
  3: "bg-chart-3",
  4: "bg-chart-4",
  5: "bg-chart-5",
