/** Props for the task names beside the chart. */
export interface TaskListProps {
  rows: GanttRow[];
  onToggle: (groupId: string) => void;
}

/**
 * The names beside the chart, one per row: groups open and close with their
 * task count, and each task shows its owner. Rows line up with the chart rows.
 */
export function TaskList({ rows, onToggle }: TaskListProps) {
  return (
    <ul aria-label="Tasks" className="border-r border-border">
      <li aria-hidden="true" className="flex h-11 items-end border-b border-border px-3 pb-1.5 text-xs text-muted-foreground">
        Tasks
      </li>
      {rows.map((row) =>
        row.kind === "group" ? (
          <li key={row.group.id} className="h-9">
            <Toggle
              pressed={row.open}
              onPressedChange={() => onToggle(row.group.id)}
              aria-label={`${row.group.name}, ${row.group.tasks.length} tasks, ${row.open ? "shown" : "hidden"}`}
              className="group relative isolate flex h-full w-full cursor-pointer items-center gap-1.5 px-2 text-left text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
            >
              <span aria-hidden="true" className="absolute inset-0 -z-10 group-hover:bg-muted/40" />
              <ChevronRightIcon aria-hidden="true" className={cn("size-4 text-muted-foreground motion-safe:transition-transform", row.open && "rotate-90")} />
              <span className="min-w-0 flex-1 truncate">{row.group.name}</span>
              <span className="text-xs tabular-nums text-muted-foreground">{row.group.tasks.length}</span>
            </Toggle>
          </li>
        ) : (
          <li key={row.task.id} className="flex h-9 items-center gap-2 pr-2 pl-7 text-sm">
            <PersonAvatar person={person(row.task.owner)} />
            <span className="min-w-0 truncate">{row.task.name}</span>
          </li>
        ),
      )}
    </ul>
  );
}

import { cn } from "@/lib/utils";

import { HUE_BORDER, HUE_FILL, type Person } from "./people";

/** Props for one person's initials badge. */
export interface PersonAvatarProps {
  person: Person;
  /** `sm` is 1.5rem, `md` is 2rem. */
  size?: "sm" | "md";
  /** Shows the name to screen readers. Leave it off when the name is already written beside the badge. */
  labelled?: boolean;
  className?: string;
}

/**
 * A round badge with a person's initials, ringed and tinted in their hue. The
 * tint is a faded layer behind the letters, so the letters keep full contrast.
 */
export function PersonAvatar({ person, size = "sm", labelled = false, className }: PersonAvatarProps) {
  return (
    <span
      role={labelled ? "img" : undefined}
      aria-label={labelled ? person.name : undefined}
      aria-hidden={labelled ? undefined : true}
      title={person.name}
      className={cn(
        "relative isolate inline-grid shrink-0 place-items-center overflow-hidden rounded-full border-2 bg-card font-semibold text-foreground",
        HUE_BORDER[person.hue],
        size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
        className,
      )}
    >
      <span aria-hidden="true" className={cn("absolute inset-0 -z-10 opacity-25", HUE_FILL[person.hue])} />
      {person.initials}
    </span>
  );
}

/** Props for a row of overlapping initials badges. */
export interface AvatarStackProps {
  people: Person[];
  /** Badges past this count fold into a "+N" badge. */
  max?: number;
  size?: "sm" | "md";
  className?: string;
}

/** A row of overlapping initials badges, named as one group, such as the people on a project. */
export function AvatarStack({ people, max = 4, size = "sm", className }: AvatarStackProps) {
  const shown = people.slice(0, max);
  const rest = people.length - shown.length;
  return (
    <span
      role="img"
      aria-label={people.map((member) => member.name).join(", ")}
      className={cn("flex items-center -space-x-1.5", className)}
    >
      {shown.map((member) => (
        <PersonAvatar key={member.id} person={member} size={size} className="ring-2 ring-card" />
      ))}
      {rest > 0 ? (
        <span
          aria-hidden="true"
          className={cn(
            "inline-grid shrink-0 place-items-center rounded-full border-2 border-border bg-card font-medium text-muted-foreground ring-2 ring-card",
            size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
          )}
        >
          +{rest}
        </span>
      ) : null}
    </span>
  );
}

